use vstd::prelude::*;
use vstd::vec::Vec;

verus! {
    // Swap the elements at indices i and j in the input vector.
    // Requires that i and j are valid indices.
    // Ensures the returned vector has the same length and is identical
    // to the input except that elements at i and j are swapped.
    fn swap(arr: &Vec<i32>, i: usize, j: usize) -> (result: Vec<i32>)
        requires
            i < arr.len(),
            j < arr.len(),
        ensures
            // The length is preserved
            result.len() == arr.len(),
            // For every valid index k:
            //   if k == i, result[k] == arr[j];
            //   else if k == j, result[k] == arr[i];
            //   otherwise result[k] == arr[k].
            forall |k: usize|
                k < arr.len() ==>
                    if k == i {
                        result[k] == arr[j]
                    } else if k == j {
                        result[k] == arr[i]
                    } else {
                        result[k] == arr[k]
                    },
    {
        // Start by cloning the input
        let mut result = arr.clone();

        // Save the two values
        let tmp_i = result[i];
        let tmp_j = result[j];

        // Perform the swap
        result[i] = tmp_j;
        result[j] = tmp_i;

        result
    }
}

